"""The §4 edge-case fixtures, generated byte-exactly.

Two things need byte control that a checked-in text file cannot express
portably, so the fixtures are written by a script that is itself part of the
deliverable:

* CRLF line endings (spec §4 requires a CRLF fixture);
* a UTF-8 BOM on one file, which the parser must tolerate (spec §2).

Run ``python3 python/tests/make_fixtures.py`` to regenerate every file under
``python/tests/fixtures/``. The files are deterministic: regeneration produces
identical bytes.
"""

import sys
from pathlib import Path
from typing import Final

FIXTURE_DIR: Final[Path] = Path(__file__).resolve().parent / "fixtures"

HEADER: Final[str] = "fecha,fecha valor,importe,saldo"

CLEAN_CSV: Final[str] = (
    "\n".join(
        [
            HEADER,
            "02/01/2026,02/01/2026,1000,1000",
            "05/01/2026,05/01/2026,-250.25,749.75",
            "05/01/2026,07/01/2026,-249.75,500.00",
            "09/01/2026,05/01/2026,13.50,513.50",  # value date moves backwards: inversion
        ]
    )
    + "\n"
)
"""A small, fully reconciled statement with exactly one value-date inversion (line 5)."""

EDGE_CASES_CSV: Final[str] = (
    "\n".join(
        [
            HEADER,
            ",,,",  # line 2: fully empty row -> skipped, not an error
            "03/01/2026,03/01/2026,10.00,10.00",
            '04/01/2026,04/01/2026,"1234,56",1244.56',  # quoted comma-decimal
            "05/01/2026,05/01/2026,abc,1244.56",  # malformed amount
            "06/01/2026,06/01/2026,1.2.3,1244.56",  # malformed amount
            "07/01/2026,07/01/2026,--5,1244.56",  # multi-sign amount
            "08/01/2026,08/01/2026,1.234,1244.56",  # ambiguous -> rejected
            "09/01/2026,09/01/2026,5.00",  # missing saldo -> short row
            "10/01/2026,2026-01-10,5.00,1249.56",  # value date not DD/MM/YYYY
            "31/02/2026,31/02/2026,5.00,1254.56",  # not a real calendar date
            ",,,",  # trailing empty row
        ]
    )
    + "\n"
)

COLLISION_CSV: Final[str] = (
    "\n".join(
        [
            HEADER,
            "01/03/2026,01/03/2026,500,500",  # opening 0.00 -> 500.00
            "10/09/2026,10/09/2026,-400,100",  # collision pair 1, member A
            "11/09/2026,11/09/2026,400,500",  # refill, so the balance can repeat
            "10/09/2026,10/09/2026,-400,100",  # collision pair 1, member B
            "01/11/2026,01/11/2026,-100,0",  # collision pair 2, member A
            "02/11/2026,02/11/2026,100,100",  # refill again
            "01/11/2026,01/11/2026,-100,0",  # collision pair 2, member B
        ]
    )
    + "\n"
)
"""Two pairs of rows identical on ``(bookingDate, amount, balanceAfter)``.

Spec §4 calls this out: any dedup keyed on natural fields silently merges real
transactions. Both members of each pair must survive parsing. The pair members
are not adjacent, exactly as in the reference file, where the three colliding
pairs sit at lines 243/247, 288/290 and 446/448.
"""

REGISTRY_JSON: Final[str] = """{
  "version": 1,
  "toleranceDays": 3,
  "accounts": [
    { "id": "A", "currency": "EUR", "openingBalance": "100.00" },
    { "id": "B", "currency": "EUR", "openingBalance": "0.00" },
    { "id": "C", "currency": "EUR", "openingBalance": "0.00" }
  ]
}
"""

REGISTRY_A_CSV: Final[str] = (
    "\n".join(
        [
            HEADER,
            "05/01/2026,05/01/2026,50.00,150.00",  # opening 100.00 -> 150.00
            "10/01/2026,10/01/2026,-250.00,-100.00",  # transfer out, booked to B
            "12/01/2026,12/01/2026,300.00,200.00",  # decoy: no counterparty anywhere
        ]
    )
    + "\n"
)

REGISTRY_B_CSV: Final[str] = (
    "\n".join(
        [
            HEADER,
            "06/01/2026,06/01/2026,250.00,250.00",  # the matching transfer in, gap 4 days -> too far
            "13/01/2026,13/01/2026,100.00,350.00",  # unrelated credit
        ]
    )
    + "\n"
)

REGISTRY_C_CSV: Final[str] = (
    "\n".join(
        [
            HEADER,
            "11/01/2026,11/01/2026,250.00,250.00",  # same magnitude, gap 1 day: the pair
        ]
    )
    + "\n"
)

REGISTRY_MISMATCH_JSON: Final[str] = """{
  "version": 1,
  "accounts": [
    { "id": "A", "currency": "EUR", "openingBalance": "999.00" }
  ]
}
"""
"""Declared opening balance that contradicts the statement's own first row."""

FILES: Final[dict[str, str]] = {
    "clean.csv": CLEAN_CSV,
    "edge_cases.csv": EDGE_CASES_CSV,
    "collision.csv": COLLISION_CSV,
    "registry.json": REGISTRY_JSON,
    "A.csv": REGISTRY_A_CSV,
    "B.csv": REGISTRY_B_CSV,
    "C.csv": REGISTRY_C_CSV,
    "registry_mismatch.json": REGISTRY_MISMATCH_JSON,
}
"""Fixture name to exact text; every file is written as UTF-8 without a BOM."""

BOM_FILES: Final[tuple[str, ...]] = ("clean.csv",)
"""Files written with a leading UTF-8 BOM, which §2 says the parser must accept."""

CRLF_FILES: Final[tuple[str, ...]] = ("collision.csv",)
"""Files written with CRLF line endings, which §4 requires to be covered."""


def write_fixtures(target: Path = FIXTURE_DIR) -> list[Path]:
    """Write every fixture under ``target`` and return the paths written."""
    target.mkdir(parents=True, exist_ok=True)
    written: list[Path] = []
    for name, text in FILES.items():
        payload = text.replace("\n", "\r\n") if name in CRLF_FILES else text
        encoding = "utf-8-sig" if name in BOM_FILES else "utf-8"
        path = target / name
        path.write_text(payload, encoding=encoding, newline="")
        written.append(path)
    return written


if __name__ == "__main__":
    names = "\n".join(path.name for path in write_fixtures())
    sys.stdout.write(names + "\n")
